VAR
    Local_Fault_Reset_Trig : R_TRIG;
    Latched_Overload : BOOL;
END_VAR

// Latch the overload alarm based on winding temperature or current, using defined tags only
IF Motor_Winding_Temp > 130.0 OR Motor_Current > (41.5 * 1.15) THEN
    Overload_Timer(IN := Motor_Running, PT := T#3S);
ELSE
    Overload_Timer(IN := FALSE, PT := T#3S);
END_IF;

Local_Fault_Reset_Trig(CLK := Fault_Reset);
IF Local_Fault_Reset_Trig.Q THEN
    Latched_Overload := FALSE;
ELSIF Overload_Timer.Q THEN
    Latched_Overload := TRUE;
END_IF;

Overload_Alarm := Latched_Overload;

// Ensure the motor stops if an overload occurs or if start command is absent
Motor_Stop := NOT Start_Command OR Latched_Overload;

